<# One post-handoff mount/observation; failures preserve the branch without recovery. #>
[CmdletBinding(SupportsShouldProcess)]param(
 [string]$HandoffResultPath,[string]$HandoffResultSha256,[string]$ApplyResultPath,[string]$ApplyResultSha256,[string]$PrepareResultPath,[string]$PrepareResultSha256,
 [ValidateSet('first-mount','clean-remount')][string]$Mode='first-mount',
 [string]$PriorVerificationResultPath,[string]$PriorVerificationResultSha256,
 [string]$ReviewedSourcesPath,[string]$ReviewedSourcesSha256,[ValidateRange(60,900)][int]$BootTimeoutSeconds=300,[ValidateRange(30,900)][int]$NativeTimeoutSeconds=300
)
Set-StrictMode -Version Latest;$ErrorActionPreference='Stop';$workspace=Split-Path -Parent $PSScriptRoot
function Get-CVSources{@('scripts/Invoke-LabConvertedVerification.ps1','scripts/Invoke-LabNativeReconstruct.ps1','scripts/Invoke-LabRetainedNativeProbe.ps1','scripts/New-LabNativeReconstructRequest.ps1','lab/Lab.psm1','lab/guest/Invoke-GuestNativeReconstruct.ps1','lab/guest/Restore-GuestShadowAttachment.ps1','lab/guest/NativeShadowDisk.cs','lab/guest/NativeShadowReadOnlyAttachment.cs','lab/guest/NativeMountBoundary.cs','lab/guest/Invoke-GuestReadOnlyMount.ps1','lab/guest/NativeRetainedFixture.cs','lab/guest/NativeRetainedFixture.Windows.cs','lab/guest/Invoke-GuestRetainedPair.ps1','lab/guest/NativeConvertedVerification.cs','lab/guest/NativeConvertedVerification.Windows.cs','lab/guest/Invoke-GuestConvertedVerification.ps1')}
function Assert-CVHash($Hash){if($Hash-isnot[string]-or$Hash-cnotmatch '\A[0-9a-f]{64}\z'){throw 'Independent SHA-256 pin required.'}}
function Assert-CVModeInputs([string]$SelectedMode,[string]$PriorPath,[string]$PriorHash){
 if($SelectedMode-cnotin@('first-mount','clean-remount')){throw 'Explicit observation mode required.'}
 if($SelectedMode-ceq'clean-remount'){
  if([string]::IsNullOrWhiteSpace($PriorPath)){throw 'Clean remount needs a completed prior observation.'};Assert-CVHash $PriorHash
 }elseif(-not[string]::IsNullOrEmpty($PriorPath)-or-not[string]::IsNullOrEmpty($PriorHash)){throw 'First mount cannot consume remount provenance.'}
}
function Assert-CVPriorObservation($Prior,$Handoff,[string]$PrepareHash,[string]$ApplyHash,[string]$HandoffHash){
 Assert-RHInteger $Prior.schemaVersion 1 1
 if($Prior.kind-cne'converted-verification-host'-or$Prior.status-cne'retained-A-observed-readonly-checkpointed'-or$Prior.phase-cne'complete'-or$Prior.runId-cne$Handoff.runId-or$Prior.vmId-cne$Handoff.vmId-or$Prior.baselineId-cne$Handoff.baselineId){throw 'Exact completed first native observation required.'}
 foreach($n in @('mountId','observationId')){if($Prior.$n-isnot[string]-or$Prior.$n-cnotmatch'\A[0-9a-f]{32}\z'){throw 'Prior observation identifiers differ.'}}
 foreach($n in @('attachmentExported','mountExported','verificationExported','retainedNativeObservationVerified','cleanShutdown','outcomeCheckpointCreated','baselineRestored','memoryRestored')){Assert-RHBool $Prior.$n $true}
 foreach($n in @('transportCompletionUnknown','guestOperationUnknown','sessionPreserved','journalRecoveryRequested','reconstructionPhaseInvoked','rawPayloadWriteRequestsIssued','conversionQualified','bootQualified')){Assert-RHBool $Prior.$n $false}
 foreach($n in @('prepareResultSha256','applyResultSha256','handoffResultSha256','requestSha256','ticketSha256','reviewedSourcesSha256','mountEvidenceSha256','verificationEvidenceSha256','inputSha256')){Assert-CVHash $Prior.$n}
 if($Prior.prepareResultSha256-cne$PrepareHash-or$Prior.applyResultSha256-cne$ApplyHash-or$Prior.handoffResultSha256-cne$HandoffHash-or$Prior.requestSha256-cne$Handoff.requestSha256-or$Prior.ticketSha256-cne$Handoff.ticketSha256-or$Prior.selectedCheckpointId-ine$Handoff.outcomeCheckpointId-or$Prior.selectedCheckpointName-cne$Handoff.outcomeCheckpointName){throw 'Prior native observation is not rooted in this exact handoff.'}
 Assert-NativeProbeGuid $Prior.outcomeCheckpointId
 if($Prior.outcomeCheckpointId-ieq$Handoff.outcomeCheckpointId-or$Prior.outcomeCheckpointName-cne('converted-readonly-'+$Prior.observationId)){throw 'Prior converted outcome checkpoint differs.'}
 $errorProperty=$Prior.PSObject.Properties['error'];if($null-ne$errorProperty-and$null-ne$errorProperty.Value){throw 'Prior observation contains an error.'}
 foreach($pair in @(@('mode','first-mount'),@('mountBoundaryInvoked',$true),@('mountEvidenceReused',$false))){$p=$Prior.PSObject.Properties[$pair[0]];if($null-ne$p){if($pair[1]-is[bool]){Assert-RHBool $p.Value $pair[1]}elseif($p.Value-cne$pair[1]){throw 'Prior first-mount mode differs.'}}}
}
function Read-CVBytes([string]$Path,[string]$Hash,[long]$Maximum){
 Assert-CVHash $Hash;$p=[IO.Path]::GetFullPath($Path);if(-not$p.StartsWith(($workspace.TrimEnd('\')+'\'),[StringComparison]::OrdinalIgnoreCase)){throw 'Input outside workspace.'};$at=$p;while($at){$f=Get-Item -LiteralPath $at -Force;if($f.Attributes-band([IO.FileAttributes]::ReparsePoint-bor[IO.FileAttributes]::Compressed-bor[IO.FileAttributes]::Encrypted)){throw 'Ordinary pinned path required.'};$at=[IO.Path]::GetDirectoryName($at)}
 $f=Get-Item -LiteralPath $p;if($f.PSIsContainer-or$f.Length-lt1-or$f.Length-gt$Maximum){throw 'Pinned input bound differs.'};$s=New-Object IO.FileStream($p,[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::Read)
 try{if($s.Length-ne$f.Length-or$s.Length-lt1-or$s.Length-gt$Maximum){throw 'Pinned file length changed.'};$b=New-Object byte[] $s.Length;$at=0;while($at-lt$b.Length){$n=$s.Read($b,$at,$b.Length-$at);if($n-le0){throw 'Short pinned read.'};$at+=$n};$sha=[Security.Cryptography.SHA256]::Create();try{$actual=[BitConverter]::ToString($sha.ComputeHash($b)).Replace('-','').ToLowerInvariant()}finally{$sha.Dispose()};if($actual-cne$Hash){throw 'Pinned content differs.'};return ,$b}finally{$s.Dispose()}
}
function Read-CVJson([string]$Path,[string]$Hash,[long]$Maximum=2MB){
 $bytes=Read-CVBytes $Path $Hash $Maximum;$text=(New-Object Text.UTF8Encoding($false,$true)).GetString($bytes)
 if($text.Length-gt0-and$text[0]-eq[char]0xfeff){$text=$text.Substring(1)}
 if($text-cmatch '\A[\x20\x09\x0a\x0d]*\uFEFF'){throw 'Only one leading UTF-8 BOM is permitted.'}
 $text|ConvertFrom-Json
}
function Import-CVGuards([byte[]]$Bytes,[string[]]$Names){$tokens=$null;$errors=$null;$ast=[Management.Automation.Language.Parser]::ParseInput((New-Object Text.UTF8Encoding($false,$true)).GetString($Bytes),[ref]$tokens,[ref]$errors);if($errors.Count){throw 'Reviewed source parse error.'};foreach($name in $Names){$f=@($ast.FindAll({param($n)$n-is[Management.Automation.Language.FunctionDefinitionAst]},$false)|Where-Object Name -CEQ $name);if($f.Count-ne1){throw 'Exact named guard missing.'};$def=[regex]::Replace($f[0].Extent.Text,('\Afunction\s+'+[regex]::Escape($name)+'\b'),('function script:'+$name));. ([scriptblock]::Create($def))}}
function Assert-CVReviewed($Review){$names=@(Get-CVSources);if($Review.schemaVersion-ne1-or$Review.kind-cne'converted-verification-reviewed-sources'-or@($Review.files).Count-ne$names.Count-or@($Review.files.path|Select-Object -Unique).Count-ne$names.Count){throw 'Exact reviewed source set required.'};foreach($f in $Review.files){if($f.path-cnotin$names){throw 'Unexpected reviewed source.'};Assert-CVHash $f.sha256}}
function Get-CVRecordedReview($Proof){
 # sourceHashes is authenticated by the independently pinned completed host
 # result. Its archived manifest was reserialized, so its bytes cannot be
 # compared to the original review-input hash stored in that result.
 $paths=@(Get-CVSources)
 if(@($Proof.sourceHashes).Count-ne$paths.Count-or@($Proof.sourceHashes.name|Select-Object -Unique).Count-ne$paths.Count){throw 'Prior reviewed-source coverage differs.'}
 $files=@(foreach($path in $paths){$name=[IO.Path]::GetFileName($path);$entry=@($Proof.sourceHashes|Where-Object name -CEQ $name);if($entry.Count-ne1){throw 'Prior source name differs.'};Assert-CVHash $entry[0].sha256;[pscustomobject]@{path=$path;sha256=$entry[0].sha256}})
 $recorded=[pscustomobject]@{schemaVersion=1;kind='converted-verification-reviewed-sources';files=$files};Assert-CVReviewed $recorded;$recorded
}
function Assert-CVPhaseHost($Proof,[string]$Operation){
 if($Proof.schemaVersion-ne1-or$Proof.kind-cne'native-reconstruction-host'-or$Proof.operation-cne$Operation-or$Proof.status-cne'native-phase-checkpointed'-or$Proof.phase-cne'complete'-or$Proof.runId-cnotmatch '\A[0-9a-f]{32}\z'-or$Proof.phaseId-cnotmatch '\A[0-9a-f]{32}\z'-or$Proof.vmId-ine'eebbfd4e-d964-4aaf-a6e6-5603fb9b6c4c'-or$Proof.baselineId-ine'eda059b3-6d50-46bb-bdf4-018b99b5b34f'-or$Proof.outcomeCheckpointName-cne('reconstruct-'+$Operation+'-'+$Proof.phaseId)){throw 'Exact completed reconstruction phase required.'}
 foreach($n in @('phaseExported','ticketExported','cleanShutdown','outcomeCheckpointCreated','baselineRestored','memoryRestored','nativeResultVerified')){Assert-RHBool $Proof.$n $true};foreach($n in @('transportCompletionUnknown','guestOperationUnknown','sessionPreserved','conversionQualified','bootQualified','automaticPhaseProgression')){Assert-RHBool $Proof.$n $false}
 foreach($n in @('requestSha256','requestPinSha256','probeResultSha256','ticketSha256','nativeReportSha256','processResultSha256','reviewedSourcesSha256')){Assert-CVHash $Proof.$n};Assert-NativeProbeGuid $Proof.outcomeCheckpointId
}
function Assert-CVChain($Prepare,$Apply,$Handoff,[string]$PrepareHash,[string]$ApplyHash){
 Assert-CVPhaseHost $Prepare prepare;Assert-CVPhaseHost $Apply apply;Assert-CVPhaseHost $Handoff handoff
 foreach($n in @('runId','vmId','baselineId','requestSha256','requestPinSha256','probeResultSha256','ticketSha256')){if($Prepare.$n-cne$Apply.$n-or$Apply.$n-cne$Handoff.$n){throw 'Phase predecessor binding differs.'}}
 if($Apply.priorResultSha256-cne$PrepareHash-or$Handoff.priorResultSha256-cne$ApplyHash-or$Apply.selectedCheckpointId-ine$Prepare.outcomeCheckpointId-or$Handoff.selectedCheckpointId-ine$Apply.outcomeCheckpointId-or$Apply.selectedCheckpointName-cne$Prepare.outcomeCheckpointName-or$Handoff.selectedCheckpointName-cne$Apply.outcomeCheckpointName-or$Apply.inputTicketSha256-cne$Prepare.ticketSha256-or$Handoff.inputTicketSha256-cne$Prepare.ticketSha256-or-not[string]::IsNullOrEmpty($Prepare.priorResultSha256)-or-not[string]::IsNullOrEmpty($Prepare.inputTicketSha256)){throw 'Exact prepare/apply/handoff chain required.'}
 if(@($Prepare.phaseId,$Apply.phaseId,$Handoff.phaseId|Select-Object -Unique).Count-ne3-or@($Prepare.outcomeCheckpointId,$Apply.outcomeCheckpointId,$Handoff.outcomeCheckpointId|Select-Object -Unique).Count-ne3){throw 'Phase identities alias.'}
}
function Assert-CVArtifacts([object[]]$Files,[string]$Stage){
 $cap=switch -CaseSensitive($Stage){attachment{1}mount{1}verification{203}default{throw 'Unknown export stage.'}};if($Files.Count-lt1-or$Files.Count-gt$cap-or@($Files.name|Select-Object -Unique).Count-ne$Files.Count){throw 'Export count differs.'};$total=0L;$raw=0L;$rawCount=0
 foreach($f in $Files){$max=0L;$minimum=1;if($Stage-ceq'attachment'-and$f.name-ceq'attachment.json'){$max=1MB}elseif($Stage-ceq'mount'-and$f.name-ceq'mount.json'){$max=2MB}elseif($Stage-ceq'verification'){switch -CaseSensitive($f.name){input.json{$max=64KB}started.json{$max=16KB}verification.json{$max=2MB}default{if($f.name-cmatch '\Aquery-[0-9]{3}\.bin\z'){$max=64KB;$minimum=0;$raw+=$f.length;$rawCount++}}}}
  Assert-CVHash $f.sha256;Assert-RHInteger $f.length $minimum $max;if($max-eq0-or([IO.FileAttributes]$f.attributes-band([IO.FileAttributes]::ReparsePoint-bor[IO.FileAttributes]::Compressed-bor[IO.FileAttributes]::Encrypted))){throw 'Export allowlist/type differs.'};$total+=$f.length
 };if($total-gt7MB-or$raw-gt4MB-or$rawCount-gt200){throw 'Export aggregate exceeds bound.'}
}
function Assert-CVMount($Mount,$Pins){
 Assert-RHBool $Mount.native.vhdOpenReadOnly $true;Assert-RHInteger $Mount.native.vhdOpenVersion 2 2;Assert-RHInteger $Mount.native.vhdOpenAccessMask 0 0
 if($Mount.schemaVersion-ne1-or$Mount.kind-cne'converted-retained-mount-boundary'-or$Mount.status-cne'converted-target-online-read-only'-or$Mount.stage-cne'complete'-or$Mount.runId-cne$runId-or$Mount.observationId-cne$mountId){throw 'Mount outcome differs.'};Assert-MountSame $Pins $Mount.pins
 foreach($n in @('operationCompletionKnown','cleanupComplete','shadowDetached','targetOnlineReadOnly','targetVolumeDiscoveryRequired')){Assert-RHBool $Mount.$n $true};foreach($n in @('privilegeAdjustmentAttempted','rawPayloadWriteRequestsIssued','filePayloadWriteRequestsIssued','writableMountRequested','convertedFileVerificationPerformed','conversionQualified','bootQualified')){Assert-RHBool $Mount.$n $false}
 foreach($n in @('BoundaryComplete','CleanupComplete','ShadowAbsent','DetachReturned','DetachSucceeded','ProtectReturned','OnlineReturned')){Assert-RHBool $Mount.native.$n $true};Assert-RHBool $Mount.native.OperationActive $false
 Assert-MountSame $request $Mount.request;Assert-MountSame $request.probe.target $Mount.expectedTarget;Assert-MountSame $shadow.shadow $Mount.expectedShadow;if($Mount.expectedPostimageSha256-cne$phaseReports.apply.native.plan.expected_postimage_sha256-or[guid]$Mount.shadowVirtualDiskId-ne[guid]$shadow.finalVhd.virtualDiskId-or$Mount.shadowIdentityQueryVersion-ne14){throw 'Mount identity/postimage differs.'}
 Assert-MountInventory @($Mount.initialDisks) $shadow $true 1 $request;Assert-MountInventory @($Mount.afterDetachDisks) $shadow $false 1 $request;Assert-MountInventory @($Mount.finalDisks) $shadow $false 2 $request
}
function Export-RetainedProbe([string]$GuestRoot,[string]$Stage,[string]$Folder){
 $scan={param($Root);$p=$Root;while($p){$d=Get-Item -LiteralPath $p -Force;if(-not$d.PSIsContainer-or($d.Attributes-band[IO.FileAttributes]::ReparsePoint)){throw 'Ordinary evidence parent required.'};$p=[IO.Path]::GetDirectoryName($p)};$items=@(Get-ChildItem -LiteralPath $Root -Force);if($items.Count-gt203){throw 'Evidence count exceeded.'};foreach($f in $items){if($f.PSIsContainer-or($f.Attributes-band[IO.FileAttributes]::ReparsePoint)-or$f.Length-gt2MB){throw 'Evidence type/size differs.'};[pscustomobject]@{name=$f.Name;length=$f.Length;attributes=[string]$f.Attributes;sha256=(Get-FileHash -LiteralPath $f.FullName).Hash.ToLowerInvariant()}}}
 $files=@(Invoke-RetainedProbeCommand -Arguments @($GuestRoot) -Body $scan);Assert-CVArtifacts $files $Stage;$dir=Join-Path $outputRoot $Folder;if(Test-Path -LiteralPath $dir){throw 'Export directory exists.'};New-Item -ItemType Directory -Path $dir|Out-Null
 foreach($f in $files){$dest=Join-Path $dir $f.name;Copy-Item -LiteralPath ($GuestRoot+'\'+$f.name) -Destination $dest -FromSession $session;$item=Get-Item -LiteralPath $dest;if($item.PSIsContainer-or$item.Length-ne$f.length-or(Get-FileHash -LiteralPath $dest).Hash.ToLowerInvariant()-cne$f.sha256){throw 'Copied artifact differs.'}}
 $after=@(Invoke-RetainedProbeCommand -Arguments @($GuestRoot) -Body $scan);Assert-CVArtifacts $after $Stage;if($after.Count-ne$files.Count){throw 'Artifact coverage changed.'};foreach($f in $files){$a=@($after|Where-Object name -CEQ $f.name);if($a.Count-ne1-or$a[0].sha256-cne$f.sha256-or$a[0].length-ne$f.length){throw 'Artifact changed during export.'}};Write-RetainedProbeJson (Join-Path $dir 'exported-files.json') $files 256KB;[pscustomobject]@{directory=$dir;files=$files}
}
function Open-CVFreshSession([string]$Name){if($script:transportUnknown-or$script:guestOperationUnknown-or$script:guestPhaseInFlight){throw 'Unknown guest activity forbids session closure.'};if($session){Remove-PSSession -Session $session;$script:session=$null};$script:session=Open-RetainedProbeSession;$policy=Initialize-LabGuestSession -Session $session;if($policy.status-cne'ready'){throw 'Guest session initialization refused.'};Write-RetainedProbeJson (Join-Path $outputRoot ($Name+'-session.json')) $policy 64KB;Copy-RetainedProbeGuestSources}
function Assert-CVVerification($Value,$Intent,$Spec,[string]$InputHash,$Files){
 if($Value.schemaVersion-ne1-or$Value.kind-cne'converted-retained-verification'-or$Value.runId-cne$Spec.runId-or$Value.observationId-cne$Spec.observationId-or$Value.inputSha256-cne$InputHash-or$Value.status-cne'retained-A-observed-through-protected-ReFS'-or$null-ne$Value.error){throw 'Completed native observation identity differs.'};Assert-MountSame $Spec $Value.input
 foreach($n in @('nativeOperationCompletionKnown','provenanceValidated')){Assert-RHBool $Value.$n $true};foreach($n in @('targetWriteRequestsIssued','protectionChanged','mountRequested','conversionQualified','bootQualified')){Assert-RHBool $Value.$n $false};Assert-ConvertedResult $Value.native
 if($Intent.schemaVersion-ne1-or$Intent.kind-cne'converted-retained-verification-intent'-or$Intent.runId-cne$Spec.runId-or$Intent.observationId-cne$Spec.observationId-or$Intent.inputSha256-cne$InputHash-or$Intent.freshVolumeGuid-cne$Value.freshVolumeGuid-or$Intent.maximumPayloadBytesRead-ne131072){throw 'Observation intent differs.'};Assert-RHBool $Intent.targetWriteRequestsMayFollow $false
 $queries=@($Value.native.openQueries)+@($Value.native.snapshots|ForEach-Object{$_.queries});$artifacts=@($Value.artifacts)
 if($queries.Count-ne$artifacts.Count-or$Files.Count-ne($artifacts.Count+3)-or@($artifacts.name|Select-Object -Unique).Count-ne$artifacts.Count-or(@($Value.native.snapshots.name)-join',')-cne'before,after,reopened,final'){throw 'Native artifact coverage/snapshots differ.'};$total=0L
 if(@($Value.native.openQueries).Count-lt1-or@($Value.native.openQueries).Count-gt40){throw 'Native opening proof coverage differs.'};$first=@($Value.native.snapshots)[0]
 foreach($snapshot in $Value.native.snapshots){Assert-RHBool $snapshot.nativeDiskVerified $true;Assert-RHBool $snapshot.readOnlyVolumeVerified $true;if(@($snapshot.queries).Count-lt1-or@($snapshot.queries).Count-gt40-or@($snapshot.queries).Count-ne@($first.queries).Count){throw 'Snapshot proof count differs.'};for($i=0;$i-lt@($snapshot.queries).Count;$i++){foreach($n in @('name','api','code','inputHex','capacity','bytesReturned','succeeded','nativeError','sha256')){if($snapshot.queries[$i].$n-cne$first.queries[$i].$n){throw 'Native snapshot evidence changed.'}}}}
 foreach($a in $artifacts){$f=@($Files|Where-Object name -CEQ $a.name);$q=@($queries|Where-Object artifact -CEQ $a.name);if($f.Count-ne1-or$q.Count-ne1-or$f[0].sha256-cne$a.sha256-or$q[0].sha256-cne$a.sha256-or$f[0].length-ne$a.length-or$q[0].bytesReturned-ne$a.length-or$q[0].capacity-lt$q[0].bytesReturned-or$q[0].capacity-gt64KB-or$q[0].succeeded-isnot[bool]){throw 'Native buffer binding differs.'};$total+=$a.length}
 if($total-ne$Value.binaryBytes-or($Files|Where-Object name -CEQ 'input.json').sha256-cne$InputHash){throw 'Observation byte accounting differs.'}
}
if(-not$PSCmdlet.ShouldProcess('exact completed converted/Handoff checkpoint','Selected protected observation; preserve every failure')){[pscustomobject]@{DryRun=$true;Mode=$Mode;HandoffReplayAllowed=$false;ConversionQualified=$false};return}
Assert-CVModeInputs $Mode $PriorVerificationResultPath $PriorVerificationResultSha256
$review=Read-CVJson $ReviewedSourcesPath $ReviewedSourcesSha256 64KB;Assert-CVReviewed $review;$sourceBytes=@{}
foreach($entry in $review.files){$sourceBytes[[IO.Path]::GetFileName($entry.path)]=Read-CVBytes (Join-Path $workspace $entry.path) $entry.sha256 256KB}
Import-CVGuards $sourceBytes['Invoke-LabNativeReconstruct.ps1'] @('Assert-RHBool','Assert-RHHash','Assert-RHInteger','Read-RHBytes','Assert-RHPin','Assert-RHProcess','Assert-RHNativeIntent')
Import-CVGuards $sourceBytes['Invoke-LabRetainedNativeProbe.ps1'] @('Convert-RetainedProtectionHex','Get-RetainedProtectionGuid','Assert-RetainedProtectionLayout','Assert-RetainedProbeProtection')
Import-CVGuards $sourceBytes['Invoke-LabRetainedNativeProbe.ps1'] @('Write-RetainedProbeJson','Copy-RetainedProbePinned','Read-RetainedProbePinned','Assert-RetainedProbeBoolean','Assert-RetainedProbePreparation','Assert-RetainedProbeCheckpoint','Set-RetainedProbeReplyState','Assert-RetainedProbeReply','Assert-RetainedProbeAttachment','Read-RetainedProbeExport','Save-RetainedProbeProgress','Invoke-RetainedProbeCommand','Open-RetainedProbeSession','Assert-RetainedProbeCurrent','Wait-RetainedProbeRestored','Complete-RetainedProbeBaseline','Copy-RetainedProbeGuestSources','Restore-RetainedProbeShadow','Stop-RetainedProbeGuest','New-RetainedProbeCheckpoint')
Import-CVGuards $sourceBytes['Invoke-GuestNativeReconstruct.ps1'] @('Assert-NRFields','Assert-NRBool','Assert-NRNumber','Assert-NRHash','Assert-NRGuid','Assert-NRSame','Assert-NRBytes','Assert-NRPartition','Assert-NRRequest','Assert-NRTicket','Assert-NROrdinarySnapshot','Assert-NRPartitionSnapshot','Assert-NRJournalSnapshot','Assert-NRResult')
Import-CVGuards $sourceBytes['Invoke-GuestReadOnlyMount.ps1'] @('Assert-MountBool','Assert-MountHash','Assert-MountInteger','Assert-MountGuid','Assert-MountSame','Assert-MountProfile','Assert-MountInputs','Assert-MountCli','Assert-MountProcess','Assert-MountProcessArtifacts','Assert-MountInventory')
Import-CVGuards $sourceBytes['Invoke-GuestRetainedPair.ps1'] @('Assert-RetainedPlatforms','Assert-RetainedAccessPolicies','Assert-RetainedNamespaces','Assert-RetainedQueryOutcome','Assert-RetainedConstruction','Assert-RetainedInspection')
Import-CVGuards $sourceBytes['Invoke-GuestConvertedVerification.ps1'] @('Assert-ConvertedBool','Assert-ConvertedInput','Get-ConvertedPin','Get-ConvertedSourcePin','Assert-ConvertedEvidence','Assert-ConvertedResult')
Import-CVGuards $sourceBytes['New-LabNativeReconstructRequest.ps1'] @('Assert-NGRHash','Assert-NGRBool','Assert-NGRNumber','Get-NGRSource','Assert-NGRHost','New-NGRRequest')
