Import-Module (Join-Path $workspace 'lab\Lab.psm1') -Force;$configuration=Get-LabConfiguration -WorkspaceRoot $workspace
if(-not([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)){throw 'Elevated Hyper-V management required.'}
$phaseHosts=@{};$phaseRoots=@{};$phaseHashes=@{prepare=$PrepareResultSha256;apply=$ApplyResultSha256;handoff=$HandoffResultSha256}
foreach($pair in @(@('prepare',$PrepareResultPath),@('apply',$ApplyResultPath),@('handoff',$HandoffResultPath))){$path=Assert-LabPath $pair[1] $configuration.Root;if([IO.Path]::GetFileName($path)-cne'host-result.json'){throw 'Exact phase host-result path required.'};$phaseHosts[$pair[0]]=Read-CVJson $path $phaseHashes[$pair[0]];$phaseRoots[$pair[0]]=Split-Path -Parent $path}
$h=$phaseHosts.handoff;$runId=$h.runId;$baselineId=$h.baselineId;$requestSha=$h.requestSha256;$ticketSha=$h.ticketSha256
$request=Read-CVJson ($phaseRoots.handoff+'\request.json') $requestSha 128KB;$pin=Read-CVJson ($phaseRoots.handoff+'\request-pin.json') $h.requestPinSha256 128KB;Assert-RHPin $pin $runId $requestSha;Assert-NRRequest $request $runId
$probeEntry=@($pin.inputs|Where-Object{[IO.Path]::GetFileName($_.path)-ceq'host-result.json'});if($probeEntry.Count-ne1-or$probeEntry[0].sha256-cne$h.probeResultSha256-or$pin.probeResultSha256-cne$h.probeResultSha256){throw 'Raw proof provenance missing.'};$probePath=Assert-LabPath $probeEntry[0].path $configuration.Root;$probeRoot=Split-Path -Parent $probePath;$hostProof=Read-CVJson $probePath $h.probeResultSha256
foreach($e in $pin.inputs){$p=Assert-LabPath $e.path $configuration.Root;$b=Read-CVBytes $p $e.sha256 2MB;if($b.Length-ne$e.length){throw 'Derived request input length differs.'}}
$probeGuard=Get-NGRSource $hostProof 'Invoke-GuestNativeProbe.ps1';Import-CVGuards (Read-CVBytes ($probeRoot+'\reviewed-sources\Invoke-GuestNativeProbe.ps1') $probeGuard.sha256 256KB) @('Assert-NativeProbeFields','Assert-NativeProbeGuid','Assert-NativeProbeBinding','Assert-NativeProbeRequest','Assert-NativeProbeSame','Assert-NativeProbeResult')
Assert-CVChain $phaseHosts.prepare $phaseHosts.apply $h $PrepareResultSha256 $ApplyResultSha256;Assert-NGRHost $hostProof
